import{_ as r,a0 as s,w as a,s as d,ao as p,I as e,x as t,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"移動版 GNOME Shell：希望之始，期望滿滿 | LCTT x X-CMD","titleTemplate":false,"description":"移動版 GNOME Shell：希望之始，期望滿滿 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"移動版 GNOME Shell：希望之始，期望滿滿 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"移動版 GNOME Shell：希望之始，期望滿滿 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion]","title":"移動版 GNOME Shell：希望之始，期望滿滿","tag":"202206","desc":""},"relativePath":"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion].md","filePath":"[post].md"}'),m={name:"202206/20220601 GNOME Shell for Mobile- A Promising Start with Huge Expectations [Opinion].md"};function u(h,l,M,g,w,E){const o=s("Link");return a(),d("div",null,[l[25]||(l[25]=p('<h1 id="移動版-gnome-shell-希望之始-期望滿滿" tabindex="-1">移動版 GNOME Shell：希望之始，期望滿滿 <a class="header-anchor" href="#移動版-gnome-shell-希望之始-期望滿滿" aria-label="Permalink to “移動版 GNOME Shell：希望之始，期望滿滿”">​</a></h1><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/GNOME-Shell-Running-on-a-prototype-Pinephone.jpg" alt="GNOME Shell 在一台 Pinephone 原型機上運行"></p><blockquote><p>GNOME 開發人員在最近的一篇博文中提出了將 GNOME Shell 完全移植到手機上的想法。下面是我對這個項目的一些看法。</p></blockquote><h3 id="移動版-gnome-shell" tabindex="-1">移動版 GNOME Shell <a class="header-anchor" href="#移動版-gnome-shell" aria-label="Permalink to “移動版 GNOME Shell”">​</a></h3>',4)),e("p",null,[l[1]||(l[1]=t("作為一個桌面環境，GNOME 在過去的十年中發展成為了 ",-1)),n(o,{href:"https://www.debugpoint.com/tag/gnome-40"},{default:i(()=>[...l[0]||(l[0]=[t("GNOME 40",-1)])]),_:1}),l[2]||(l[2]=t("。GNOME 40 是一個重要的版本，它以一種現代的方式改變了完整的用户界面設計。",-1))]),l[26]||(l[26]=e("p",null,"看着 GNOME 40 的設計方式，你可能會覺得 Shell 和它的底層技術已經為小屏幕做好了準備。手勢驅動的工作區、圖標網格和停靠區 —— 在某種程度上感覺更接近於像安卓這樣的移動操作系統，而不是桌面環境。",-1)),l[27]||(l[27]=e("p",null,"此外，系統托盤、日曆、通知和原生的應用程序，可以有效地在較小尺寸的設備上工作。得益於 GTK4 和 libadwaita，其設計是響應式的，應用程序和控件的外觀與移動平台很匹配。",-1)),l[28]||(l[28]=e("p",null,"在 GNOME 40 之後，GNOME 開發者為較小尺寸的設備（如平板電腦和手機）設計了幾個 GNOME Shell 的概念驗證。",-1)),l[29]||(l[29]=e("h4",{id:"為什麼是現在",tabindex:"-1"},[t("為什麼是現在？ "),e("a",{class:"header-anchor",href:"#為什麼是現在","aria-label":"Permalink to “為什麼是現在？”"},"​")],-1)),e("p",null,[l[4]||(l[4]=t("任何項目的開發和研究工作都要花費時間和金錢。雖然有來自主要科技公司對 GNOME 的捐贈，但這次有一個 “",-1)),l[5]||(l[5]=e("ruby",null,[t("原型基金"),e("rt",null,"Prototype Fund")],-1)),l[6]||(l[6]=t("” 幫助該團隊繼續進行這項努力。",-1)),n(o,{href:"http://www.prototypefund.de"},{default:i(()=>[...l[3]||(l[3]=[t("原型基金",-1)])]),_:1}),l[7]||(l[7]=t(" 是德國教育部（BMBF）支持公共利益軟件的資助項目。",-1))]),l[30]||(l[30]=p('<h4 id="包括什麼" tabindex="-1">包括什麼？ <a class="header-anchor" href="#包括什麼" aria-label="Permalink to “包括什麼？”">​</a></h4><p>設計一個完整的移動用户界面，並將其與移動操作系統整合是一個非常複雜的項目。它需要一個精心設計的願景來支持成千上萬的移動硬件和用户支持。更不用説，用户在移動設備上的隱私和安全問題了。</p><p>因此，有了這個基金，團隊可以集中精力進行概念驗證，以滿足 GNOME Shell 中一些基本的用户互動。</p><ul><li>啓動器</li><li>應用程序網格</li><li>輕掃、手勢和導航</li><li>用手機鍵盤搜索</li><li>檢測屏幕大小和支持屏幕旋轉</li><li>工作空間和多任務</li><li>設置</li><li>屏幕鍵盤</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/GNOME-Shell-Mobile-mock-up.jpg" alt="GNOME Shell 移動版模擬圖"></p><p>始終要記住的是，移動體驗遠不止用户界面這麼簡單。另外，GNOME 本身並不是一個操作系統。它由底層的穩定的操作系統組成，它提供了非常需要的隱私和安全。另外，“應用商店”的概念也是如此。手機制造商需要與 GNOME 開發者合作，讓他們的產品採用這個概念。</p><h4 id="進展如何" tabindex="-1">進展如何？ <a class="header-anchor" href="#進展如何" aria-label="Permalink to “進展如何？”">​</a></h4><p>在寫這篇文章時，團隊給我們快速演示了取得的進展。在下面的視頻中可以看到：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/phone.webm" alt=""></p><p>複雜的任務是識別觸摸屏手機中的各種手勢。例如，你可能會使用長觸摸、短觸摸、雙指輕掃和拖動，以及許多隻有在小尺寸設備中才可行的可能性。這需要在各自的 GNOME Shell 組件中推倒重構。</p><p>而完全在現有的 GNOME Shell 基礎上開發它們是很有挑戰性的工作。</p><p>此外，該團隊使用著名的 Pinephone Pro 進行開發和測試。Pinephone 已經是一個商業產品，裝有 “友商” KDE Plasma 手機和其他 Linux 操作系統。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/06/tablet.webm" alt=""></p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>如果一切按計劃進行，我們可能在一個完整的開源手機中獲得原生的 GNOME 體驗。而你可以重新擁有你的隱私!</p><p>另外，我不確定 Phosh（它也是基於 GNOME 的）會發生什麼。雖然 Phosh 是由 Purism 開發和管理的，但看看 GNOME Shell 在移動設備上的努力和 PHosh 在未來一段日子的發展方向將是很有趣的。</p><p>那麼，你對這個項目的前景怎麼看？請在下面的評論欄裏告訴我。</p>',17)),e("p",null,[e("em",null,[l[9]||(l[9]=t("圖片和視頻來源：GNOME 開發者 ",-1)),n(o,{href:"https://blogs.gnome.org/shell-dev/2022/05/30/towards-gnome-shell-on-mobile/"},{default:i(()=>[...l[8]||(l[8]=[t("Blog",-1)])]),_:1})])]),l[31]||(l[31]=e("hr",null,null,-1)),e("p",null,[l[11]||(l[11]=t("via: ",-1)),n(o,{href:"https://www.debugpoint.com/2022/06/gnome-shell-mobile-announcement/"},{default:i(()=>[...l[10]||(l[10]=[t("https://www.debugpoint.com/2022/06/gnome-shell-mobile-announcement/",-1)])]),_:1})]),e("p",null,[l[16]||(l[16]=t("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...l[12]||(l[12]=[t("Arindam",-1)])]),_:1}),l[17]||(l[17]=t(" 選題：",-1)),n(o,{href:"https://github.com/lkxed"},{default:i(()=>[...l[13]||(l[13]=[t("lkxed",-1)])]),_:1}),l[18]||(l[18]=t(" 譯者：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...l[14]||(l[14]=[t("wxy",-1)])]),_:1}),l[19]||(l[19]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...l[15]||(l[15]=[t("wxy",-1)])]),_:1})]),e("p",null,[l[22]||(l[22]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[20]||(l[20]=[t("LCTT",-1)])]),_:1}),l[23]||(l[23]=t(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...l[21]||(l[21]=[t("Linux中國",-1)])]),_:1}),l[24]||(l[24]=t(" 榮譽推出",-1))])])}const f=r(m,[["render",u]]);export{b as __pageData,f as default};
